        <p style="color: var(--text-muted); font-size: 14px; margin-top: 4px;">Target: <strong>${a.config.targetUrl}</strong> | Role: <strong>${a.config.userRole||"Admin"}</strong> | Browser: <strong>${a.config.browser||"Chromium"}</strong></p>
